 "content": "def transform(grid):
    """Copy the marked shape onto every translated all-zero footprint."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    if not counts:
        return out
    background = max(counts, key=counts.get)
    markers = {v for row in grid for v in row if v not in (0, background)}
    if not markers:
        return out
    marker = min(markers, key=lambda v: sum(x == v for row in grid for x in row))
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker]
    min_r = min(r for r, c in points)
    max_r = max(r for r, c in points)
    min_c = min(c for r, c in points)
    max_c = max(c for r, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    sh, sw = max_r - min_r + 1, max_c - min_c + 1
    for top in range(h - sh + 1):
        for left in range(w - sw + 1):
            # The original marker is not a destination; other copies occupy zeros only.
            if all(grid[top + dr][left + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[top + dr][left + dc] = marker
    return out

if __name__ == '__main__':
    import sys, json
    print(json.dumps(transform(json.load(sys.stdin))))
